import math

def interp(points,u):
    ps=sorted(points)
    for (x,y),(xx,yy) in zip(ps,ps[1:]):
        if x<=u<=xx and xx-x>0.001:
            return y+(yy-y)*(u-x)/(xx-x)
    return None

def control(obs):
    m=obs['local_map']
    left=m['left_rail']; right=m['right_rail']
    def center(u):
        a=interp(left,u); b=interp(right,u)
        return None if a is None or b is None else (a+b)/2
    target=None
    for u in [13,11,9,7,5,3]:
        v=center(u)
        if v is not None:
            target=(u,v); break
    if target is None:
        return (obs['hitch_deg'],0)
    u,v=target
    k=2*v/((u+1.9)**2+v*v)
    hd=math.degrees(math.asin(max(-0.78,min(0.78,10.2*k))))
    h=obs['hitch_deg']
    feed=math.degrees(math.atan(3.9*math.sin(math.radians(h))/(10.2+0.35*math.cos(math.radians(h)))))
    steer=max(-42,min(42,feed+1.65*(h-hd)))
    speed=1.5 if abs(hd)<10 else 1.0
    if abs(h-hd)>15: speed=0.7
    return (steer,-speed,180)

